    let cpu_norm = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let ram_norm = node_residual_ram as f64 / node_capacity_ram as f64;
    let imbalance_penalty = (cpu_norm - ram_norm).abs();

    // Dynamic horizon awareness
    let step_normalized = step_index as f64 / total_jobs as f64;
    let penalty_step = if step_normalized < 0.3 { 1.0 } else if step_normalized > 0.7 { 2.0 } else { 1.5 };

    // Lookahead awareness
    let next_job_fits_cpu = node_residual_cpu >= next_job_cpu;
    let next_job_fits_ram = node_residual_ram >= next_job_ram;
    let lookahead_penalty = if next_job_fits_cpu && next_job_fits_ram { 0.0 } else { 1.5 };

    // Non-linear conditionals
    let cpu_usage_ratio = node_capacity_cpu as f64 / active_nodes_count as f64;
    let ram_usage_ratio = node_capacity_ram as f64 / active_nodes_count as f64;
    let cpu_penalty = if cpu_norm > 0.8 { cpu_norm.powi(2) } else { cpu_norm };
    let ram_penalty = if ram_norm > 0.8 { ram_norm.powi(2) } else { ram_norm };

    // Imbalance penalties
    let imbalance_adjustment = (cpu_norm - ram_norm).abs() * active_nodes_count as f64;

    // Bin residual space or dead space ratio
    let bin_residuum_ratio_cpu = node_residual_cpu as f64 / node_capacity_cpu as f64;
    let bin_residuum_ratio_ram = node_residual_ram as f64 / node_capacity_ram as f64;
    let bin_residuum_penalty = (bin_residuum_ratio_cpu - bin_residuum_ratio_ram).abs();

    // Lookahead packing bonuses
    let lookahead_bonus = if next_job_fits_cpu && next_job_fits_ram { 0.5 } else { 0.0 };

    // Combined residual fitting and lookahead anticipation
    let combined_fit_penalty = if next_job_fits_cpu && next_job_fits_ram {
        (node_residual_cpu - job_cpu) as f64 * (node_residual_ram - job_ram) as f64
    } else {
        1.0
    };

    // Combine all components
    let score = cpu_penalty + ram_penalty - imbalance_penalty - imbalance_adjustment + penalty_step + lookahead_penalty + bin_residuum_penalty + lookahead_bonus - combined_fit_penalty;
    score
}

pub fn score_node(job_cpu: u32, job_ram: u32, node_residual_cpu: u32, node_residual_ram: u32, node_capacity_cpu: u32, node_capacity_ram: u32, step_index: usize, total_jobs: usize, active_nodes_count: usize, mean_cpu_residual: f64, mean_ram_residual: f64, next_job_cpu: u32, next_job_ram: u32) -> f64 {
