    let packing_bonus = if node_residual_cpu + job_cpu <= node_capacity_cpu && node_residual_ram + job_ram <= node_capacity_ram { 0.2 } else { 0.0 };

    let score = cpu_norm * ram_norm - imbalance_penalty * (node_utilization * horizon_factor * lookahead_factor) + packing_bonus;
    score
}

